  let level = 0;
  while (2 ** (level + 1) <= label) {
    level++;
  }
  const path = [];
  while (label >= 1) {
    path.push(label);
    const low = 2 ** level;
    const high = 2 ** (level + 1) - 1;
    label = Math.floor((low + high - label) / 2);
    level--;
  }
