function pathInZigZagTree(label) {
  // Build every row explicitly, listed left to right, until the label's row exists.
  const rows = [[1]];
  while (rows[rows.length - 1].every(v => v < label)) {
    const prev = rows[rows.length - 1];
    const first = prev.length * 2, count = prev.length * 2;
    const row = Array.from({ length: count }, (_, i) => first + i);
    if (rows.length % 2 === 1) row.reverse();
    rows.push(row);
  }
  let r = rows.length - 1;
  let index = rows[r].indexOf(label);
  const result = [];
  while (r >= 0) {
    result.unshift(rows[r][index]);
    index = Math.floor(index / 2);
    r--;
  }
  return result;
}

